1	//! In-process fault-injection transport, for exercising RPC failure modes without a node.
2	//!
3	//! The retry/failover layer is the bot's only defence against a lagging, lying or
4	//! rate-limiting endpoint, and every one of those conditions is impractical to produce
5	//! against a real anvil devnet. This module implements a [`tower::Service`] with the same
6	//! shape alloy's real HTTP transport has (`Service<RequestPacket, Response = ResponsePacket,
7	//! Error = TransportError, Future = TransportFut<'static>>`), so a `DynProvider` can be built
8	//! on top of it and driven through the production code paths unmodified.
9	//!
10	//! A near-identical copy lives in `tests/fake_rpc/mod.rs` for the integration tests; the
11	//! duplication is deliberate, so that `tests/` never depends on `#[cfg(test)]` internals of
12	//! the library and no test-only plumbing leaks into the crate's public API.
13	
14	#![allow(dead_code)]
15	
16	use alloy::network::Ethereum;
17	use alloy::primitives::{Address, B256, U256};
18	use alloy::providers::{DynProvider, ProviderBuilder};
19	use alloy::rpc::client::RpcClient;
20	use alloy::rpc::json_rpc::{
21	    ErrorPayload, RequestPacket, Response, ResponsePacket, ResponsePayload, SerializedRequest,
22	};
23	use alloy::transports::{TransportError, TransportErrorKind, TransportFut};
24	use std::borrow::Cow;
25	use std::sync::{Arc, Mutex};
26	use std::task::{Context, Poll};
27	use tower::Service;
28	
29	/// One JSON-RPC request as seen by the fake endpoint.
30	#[derive(Clone, Debug)]
31	pub struct Call {
32	    /// 0-based index over every request this transport has served.
33	    pub index: usize,
34	    /// 0-based index over requests for this same method only. Makes "fail the first two
35	    /// `eth_getBlockByNumber` calls" scriptable without the test tracking counters itself.
36	    pub method_index: usize,
37	    pub method: String,
38	    pub params: serde_json::Value,
39	}
40	
41	impl Call {
42	    /// First positional parameter, or `Null`. Most eth_ methods this bot issues are
43	    /// dispatched on it (a block tag, or the call object).
44	    pub fn param(&self, i: usize) -> &serde_json::Value {
45	        self.params.get(i).unwrap_or(&serde_json::Value::Null)
46	    }
47	
48	    /// Calldata of an `eth_call`, lowercased hex with `0x` prefix, or `""`.
49	    pub fn calldata(&self) -> String {
50	        self.param(0)
51	            .get("data")
52	            .or_else(|| self.param(0).get("input"))
53	            .and_then(|d| d.as_str())
54	            .unwrap_or("")
55	            .to_ascii_lowercase()
56	    }
57	
58	    /// True when this is an `eth_call` whose 4-byte selector matches `selector`.
59	    pub fn selector_is(&self, selector: [u8; 4]) -> bool {
60	        self.method == "eth_call"
61	            && self
62	                .calldata()
63	                .starts_with(&alloy::primitives::hex::encode_prefixed(selector))
64	    }
65	}
66	
67	/// What the fake endpoint does with one request.
68	#[derive(Debug)]
69	pub enum Fault {
70	    /// A JSON-RPC success carrying this `result`. Use [`Fault::null`] for the
71	    /// `"result": null` a mid-sync node returns for a block that does exist.
72	    Ok(serde_json::Value),
73	    /// A JSON-RPC *error object* delivered over an otherwise successful HTTP 200 - the case
74	    /// alloy's `FallbackLayer` does not score down on its own (see `ErrorAwareTransport`).
75	    RpcError { code: i64, message: String },
76	    /// A transport-level failure: connection refused, HTTP 5xx, HTTP 429.
77	    Transport(TransportError),
78	    /// A future that never resolves. Models an endpoint that accepted the connection and
79	    /// then went away; the real transport has a 30s reqwest timeout, the fake has none, so
80	    /// a test pairs this with `tokio::time::timeout` under a paused clock.
81	    Hang,
82	}
83	
84	impl Fault {
85	    /// `"result": null`, as returned by a node that is behind the block it was asked for.
86	    pub fn null() -> Self {
87	        Self::Ok(serde_json::Value::Null)
88	    }
89	
90	    /// HTTP 429. alloy classifies this as retryable (`HttpError::is_rate_limit_err`).
91	    pub fn rate_limited() -> Self {
92	        Self::Transport(TransportErrorKind::http_error(
93	            429,
94	            "rate limit exceeded".to_string(),
95	        ))
96	    }
97	
98	    /// Connection-level failure, as if the endpoint were down.
99	    pub fn unreachable() -> Self {
100	        Self::Transport(TransportErrorKind::custom_str(
101	            "error sending request: connection refused",
102	        ))
103	    }
104	}
105	
106	/// A scriptable, in-process alloy transport.
107	///
108	/// Cheap to clone; clones share the script and the call log, because alloy clones the
109	/// transport internally when building the client.
110	#[derive(Clone)]
111	pub struct FaultTransport {
112	    script: Arc<dyn Fn(&Call) -> Fault + Send + Sync>,
113	    log: Arc<Mutex<Vec<String>>>,
114	}
115	
116	impl FaultTransport {
117	    pub fn new<F>(script: F) -> Self
118	    where
119	        F: Fn(&Call) -> Fault + Send + Sync + 'static,
120	    {
121	        Self {
122	            script: Arc::new(script),
123	            log: Arc::new(Mutex::new(Vec::new())),
124	        }
125	    }
126	
127	    /// A `DynProvider` speaking to this fake endpoint, built the same way `config.rs`
128	    /// builds the real single-URL provider.
129	    pub fn provider(&self) -> DynProvider<Ethereum> {
130	        let client = RpcClient::builder().transport(self.clone(), false);
131	        DynProvider::new(ProviderBuilder::new().connect_client(client))
132	    }
133	
134	    /// Total requests served, including the ones that failed.
135	    pub fn call_count(&self) -> usize {
136	        self.methods().len()
137	    }
138	
139	    /// Requests served for one method.
140	    pub fn count_of(&self, method: &str) -> usize {
141	        self.methods().iter().filter(|m| *m == method).count()
142	    }
143	
144	    /// Method names in the order they were received.
145	    pub fn methods(&self) -> Vec<String> {
146	        match self.log.lock() {
147	            Ok(log) => log.clone(),
148	            // A poisoned log means some other test thread panicked; surface the data anyway
149	            // rather than turning it into a second, confusing panic.
150	            Err(poisoned) => poisoned.into_inner().clone(),
151	        }
152	    }
153	
154	    fn record(&self, method: &str, params: serde_json::Value) -> Call {
155	        // The guard is taken, used and dropped without crossing an await, matching the
156	        // convention the stores in `tasks/mod.rs` follow for `std::sync::Mutex`.
157	        let mut log = match self.log.lock() {
158	            Ok(log) => log,
159	            Err(poisoned) => poisoned.into_inner(),
160	        };
161	        let index = log.len();
162	        let method_index = log.iter().filter(|m| m.as_str() == method).count();
163	        log.push(method.to_string());
164	        drop(log);
165	
166	        Call {
167	            index,
168	            method_index,
169	            method: method.to_string(),
170	            params,
171	        }
172	    }
173	}
174	
175	impl Service<RequestPacket> for FaultTransport {
176	    type Response = ResponsePacket;
177	    type Error = TransportError;
178	    type Future = TransportFut<'static>;
179	
180	    fn poll_ready(&mut self, _cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
181	        Poll::Ready(Ok(()))
182	    }
183	
184	    fn call(&mut self, req: RequestPacket) -> Self::Future {
185	        let is_batch = matches!(req, RequestPacket::Batch(_));
186	        let requests: Vec<SerializedRequest> = match req {
187	            RequestPacket::Single(r) => vec![r],
188	            RequestPacket::Batch(rs) => rs,
189	        };
190	
191	        let mut replies = Vec::with_capacity(requests.len());
192	        for r in &requests {
193	            let params = r
194	                .params()
195	                .and_then(|p| serde_json::from_str(p.get()).ok())
196	                .unwrap_or(serde_json::Value::Null);
197	            let call = self.record(r.method(), params);
198	
199	            let payload = match (self.script)(&call) {
200	                // A hang or a transport error takes down the whole packet, which is what a
201	                // real HTTP transport does too.
202	                Fault::Hang => return Box::pin(std::future::pending()),
203	                Fault::Transport(e) => return Box::pin(async move { Err(e) }),
204	                Fault::Ok(v) => ResponsePayload::Success(
205	                    serde_json::value::to_raw_value(&v)
206	                        .expect("fault script returned non-serializable JSON"),
207	                ),
208	                Fault::RpcError { code, message } => ResponsePayload::Failure(ErrorPayload {
209	                    code,
210	                    message: Cow::Owned(message),
211	                    data: None,
212	                }),
213	            };
214	            replies.push(Response {
215	                id: r.id().clone(),
216	                payload,
217	            });
218	        }
219	
220	        let packet = if is_batch {
221	            ResponsePacket::Batch(replies)
222	        } else {
223	            match replies.pop() {
224	                Some(reply) => ResponsePacket::Single(reply),
225	                None => return Box::pin(async { Err(TransportErrorKind::custom_str("empty request packet")) }),
226	            }
227	        };
228	        Box::pin(async move { Ok(packet) })
229	    }
230	}
231	
232	/// JSON body of an `eth_getBlockByNumber` reply carrying the given number and timestamp.
233	///
234	/// Every other header field is left at its default: nothing in this crate's block handling
235	/// reads them, and a test that starts depending on one should set it explicitly.
236	pub fn block(number: u64, timestamp: u64) -> serde_json::Value {
237	    let mut b = alloy::rpc::types::Block::default();
238	    b.header.hash = B256::from(U256::from(number));
239	    b.header.inner.number = number;
240	    b.header.inner.timestamp = timestamp;
241	    serde_json::to_value(&b).expect("block is serializable")
242	}
243	
244	/// ABI-encoded return data for a call returning one 32-byte word (`uint256`, `uint64`, ...).
245	pub fn word(value: u64) -> serde_json::Value {
246	    serde_json::Value::String(alloy::primitives::hex::encode_prefixed(B256::from(
247	        U256::from(value),
248	    )))
249	}
250	
251	/// ABI-encoded return data for a call returning an `address`.
252	pub fn address_word(addr: Address) -> serde_json::Value {
253	    serde_json::Value::String(alloy::primitives::hex::encode_prefixed(
254	        addr.into_word(),
255	    ))
256	}
