18	/// Backoff applied *before* each retry; the number of attempts is one more than
19	/// the number of delays (initial call + one retry per delay).
20	const RPC_RETRY_DELAYS: [Duration; 3] = [
21	    Duration::from_secs(5),
22	    Duration::from_secs(15),
23	    Duration::from_secs(45),
24	];
25	
26	const RPC_MAX_ATTEMPTS: usize = RPC_RETRY_DELAYS.len() + 1;
27	
28	pub(crate) const RECEIPT_TIMEOUT: Duration = Duration::from_secs(120);
29	
30	/// Percentage a replacement transaction must reach relative to the one it replaces.
31	///
32	/// Geth's default `--txpool.pricebump` is 10%, applied to `maxFeePerGas` and
33	/// `maxPriorityFeePerGas` independently - bumping only one is rejected. 112 leaves
34	/// headroom for integer truncation and for nodes configured above the default.
35	const FEE_BUMP_PERCENT: u128 = 112;
36	
37	/// Ceiling on a replacement fee, as a multiple of the current market estimate.
38	/// Resending every dispatcher cycle compounds, so escalation has to stop somewhere.
39	const FEE_CEILING_MULTIPLE: u128 = 4;
40	
41	/// Fee for a replacement transaction: at least `FEE_BUMP_PERCENT` of what the stuck
42	/// transaction paid (or the node rejects it as underpriced), and at least the current
43	/// market rate (or it clears the mempool's rule but still will not be mined).
44	///
45	/// Returns `None` once the result would exceed the ceiling, meaning: stop bumping and
46	/// keep waiting. The last replacement stays in the mempool and remains mineable, so
47	/// the deposit is never at risk of being spent twice however long it takes.
48	pub(crate) fn bumped_fee(previous: u128, market_estimate: u128) -> Option<u128> {
49	    let bumped = (previous.saturating_mul(FEE_BUMP_PERCENT) / 100).max(market_estimate);
50	    let ceiling = market_estimate.saturating_mul(FEE_CEILING_MULTIPLE);
51	    (bumped <= ceiling).then_some(bumped)
52	}
53	
54	/// Retries `f` with [`RPC_RETRY_DELAYS`] backoff, returning the last error if every
55	/// attempt fails. Callers decide what a failure means: startup paths that cannot
56	/// continue should use [`retry_rpc_or_panic`], while long-running loops should
57	/// handle the error and keep going.
58	pub(crate) async fn retry_rpc<T, E, F, Fut>(op_name: impl std::fmt::Display, mut f: F) -> Result<T, E>
59	where
60	    F: FnMut() -> Fut,
61	    Fut: std::future::Future<Output = Result<T, E>>,
62	    E: std::fmt::Display,
63	{
64	    for attempt in 0..RPC_MAX_ATTEMPTS {
65	        match f().await {
66	            Ok(v) => return Ok(v),
67	            Err(e) => match RPC_RETRY_DELAYS.get(attempt) {
68	                Some(delay) => {
69	                    warn!(logger = "RPC", op = %op_name, attempt = attempt + 1, "{op_name} failed: {e}, retrying...");
70	                    sleep(*delay).await;
71	                }
72	                None => return Err(e),
73	            },
74	        }
75	    }
76	    unreachable!()
77	}
78	
79	/// Like [`retry_rpc`], but also retries when the node answers `null`.
80	///
81	/// A node that is behind or mid-sync can return `null` for a block that does exist,
82	/// and with several transports racing it is often the fastest to answer — there is
83	/// no block to fetch. Treating that as success hands `None` straight to callers that
84	/// panic on it, when a single retry would usually have cleared it.
85	pub(crate) async fn retry_rpc_opt<T, E, F, Fut>(op_name: impl std::fmt::Display, mut f: F) -> Result<Option<T>, E>
86	where
87	    F: FnMut() -> Fut,
88	    Fut: std::future::Future<Output = Result<Option<T>, E>>,
89	    E: std::fmt::Display,
90	{
91	    for attempt in 0..RPC_MAX_ATTEMPTS {
92	        let result = f().await;
93	        if let Ok(Some(_)) = &result {
94	            return result;
95	        }
96	        match RPC_RETRY_DELAYS.get(attempt) {
97	            Some(delay) => {
98	                match &result {
99	                    Ok(_) => warn!(logger = "RPC", op = %op_name, attempt = attempt + 1, "{op_name} returned null, retrying..."),
100	                    Err(e) => warn!(logger = "RPC", op = %op_name, attempt = attempt + 1, "{op_name} failed: {e}, retrying..."),
101	                }
102	                sleep(*delay).await;
103	            }
104	            None => return result,
105	        }
106	    }
107	    unreachable!()
108	}
109	
110	/// Fail-fast wrapper around [`retry_rpc`] for paths where there is no meaningful
111	/// way to continue (startup checks, config loading).
112	pub(crate) async fn retry_rpc_or_panic<T, E, F, Fut>(op_name: impl std::fmt::Display, f: F) -> T
113	where
114	    F: FnMut() -> Fut,
115	    Fut: std::future::Future<Output = Result<T, E>>,
116	    E: std::fmt::Display,
117	{
118	    retry_rpc(&op_name, f)
119	        .await
120	        .unwrap_or_else(|e| panic!("Failed to {op_name} after {RPC_MAX_ATTEMPTS} attempts: {e}"))
121	}
122	
123	async fn get_block_with_retry(provider: &DynProvider<Ethereum>, block_num: alloy::eips::BlockNumberOrTag) -> Block {
124	    retry_rpc_opt(std::fmt::from_fn(|f| write!(f, "get block {block_num}")), || async { provider.get_block_by_number(block_num).await }).await
125	        .unwrap_or_else(|e| panic!("Failed to get block {block_num}: {e}"))
126	        .unwrap_or_else(|| panic!("Block {block_num} not found"))
127	}
128	
129	pub async fn find_block_by_timestamp(provider: &DynProvider<Ethereum>, target_ts: u64) -> u64 {
130	    find_block_by_timestamp_from(provider, target_ts, 0).await
131	}
132	
133	/// Like [`find_block_by_timestamp`], but seeds the search at `lo` rather than block 0.
134	///
135	/// The indexer's target only moves forward, so its previous answer is a valid lower
136	/// bound. Searching the whole chain each time costs ~28 block fetches on Arbitrum,
137	/// multiplied by the active transport count, every idle cycle, per chain, per route —
138	/// to rediscover a block already known. Seeding cuts that to the log of one cycle's
139	/// worth of blocks.
140	///
141	/// A stale `lo` above the true answer is safe: the search then returns `lo` itself,
142	/// which the caller has already scanned past, so no blocks are skipped.
143	pub async fn find_block_by_timestamp_from(
144	    provider: &DynProvider<Ethereum>,
145	    target_ts: u64,
146	    lo: u64,
147	) -> u64 {
148	    let latest = get_block_with_retry(provider, Default::default()).await;
149	    let latest_num = latest.header.number;
150	
151	    if target_ts >= latest.header.timestamp {
152	        return latest_num;
153	    }
154	
155	    let mut lo = lo.min(latest_num);
156	    let mut hi = latest_num;
157	
158	    while lo < hi {
159	        let mid = lo + (hi - lo) / 2;
160	        let block = get_block_with_retry(provider, mid.into()).await;
161	        if block.header.timestamp < target_ts {
162	            lo = mid + 1;
163	        } else {
164	            hi = mid;
165	        }
166	    }
167	    lo
168	}
