171	mod tests {
172	    use super::*;
173	
174	    const GWEI: u128 = 1_000_000_000;
175	
176	    #[test]
177	    fn bump_clears_geth_ten_percent_threshold() {
178	        // Market roughly level with what the stuck tx paid - the realistic stall.
179	        let out = bumped_fee(30 * GWEI, 30 * GWEI).unwrap();
180	        assert!(out >= 30 * GWEI * 110 / 100, "{out} does not clear a 10% pricebump over 30 gwei");
181	    }
