183	    #[test]
184	    fn no_bump_when_already_far_above_market() {
185	        // Paying 30 gwei into a 1 gwei market: the tx will mine on its own merits, and
186	        // bumping past the ceiling would only overpay. Holding is the right answer.
187	        assert_eq!(bumped_fee(30 * GWEI, GWEI), None);
188	    }
189	
190	    #[test]
191	    fn bump_floors_at_market_when_market_has_risen() {
192	        // 112% of 10 gwei is still far under a 50 gwei market: it would be accepted as a
193	        // replacement yet never mined, so the market rate has to win.
194	        assert_eq!(bumped_fee(10 * GWEI, 50 * GWEI), Some(50 * GWEI));
195	    }
196	
197	    #[test]
198	    fn bump_stops_at_ceiling() {
199	        // Already at 4x market; another 12% would exceed it.
200	        assert_eq!(bumped_fee(40 * GWEI, 10 * GWEI), None);
201	    }
202	
203	    #[test]
204	    fn bump_allowed_below_ceiling() {
205	        assert!(bumped_fee(20 * GWEI, 10 * GWEI).is_some(), "2x market is inside the 4x ceiling");
206	    }
207	
208	    #[test]
209	    fn does_not_overflow_on_extreme_inputs() {
210	        // Degenerate values cannot occur in practice; the requirement is simply that
211	        // the arithmetic saturates instead of panicking in debug builds.
212	        let _ = bumped_fee(u128::MAX / 2, u128::MAX);
213	        let _ = bumped_fee(u128::MAX, GWEI);
214	        let _ = bumped_fee(0, 0);
215	    }
216	}
