218	/// Tests for the retry layer.
219	///
220	/// All of these run on a paused tokio clock: `retry_rpc` sleeps 5+15+45 = 65 seconds
221	/// across a full exhaustion, and the schedule itself is part of what is being asserted,
222	/// so virtual time is both the fast and the precise option.
223	#[cfg(test)]
224	mod retry_tests {
225	    use super::*;
226	    use std::sync::{Arc, Mutex};
227	    use tokio::time::Instant;
228	
229	    type BoxErr = Box<dyn std::error::Error + Send + Sync>;
230	
231	    /// Records the virtual time of every attempt, so a test can assert the backoff
232	    /// schedule rather than just the attempt count.
233	    #[derive(Default)]
234	    struct Attempts {
235	        at: Mutex<Vec<Instant>>,
236	    }
237	
238	    impl Attempts {
239	        /// Logs one attempt and returns its 0-based index.
240	        fn record(&self) -> usize {
241	            let mut at = self.at.lock().expect("attempt log");
242	            at.push(Instant::now());
243	            at.len() - 1
244	        }
245	
246	        fn count(&self) -> usize {
247	            self.at.lock().expect("attempt log").len()
248	        }
249	
250	        /// The delay observed before each retry, i.e. the applied backoff schedule.
251	        fn gaps(&self) -> Vec<Duration> {
252	            let at = self.at.lock().expect("attempt log");
253	            at.windows(2).map(|w| w[1] - w[0]).collect()
254	        }
255	    }
256	
257	    #[tokio::test(start_paused = true)]
258	    async fn succeeds_without_sleeping_when_the_first_attempt_works() {
259	        let attempts = Arc::new(Attempts::default());
260	        let a = attempts.clone();
261	        let start = Instant::now();
262	
263	        let out: Result<u64, BoxErr> = retry_rpc("healthy call", move || {
264	            let a = a.clone();
265	            async move {
266	                a.record();
267	                Ok(7)
268	            }
269	        })
270	        .await;
271	
272	        assert_eq!(out.expect("first attempt succeeds"), 7);
273	        assert_eq!(attempts.count(), 1);
274	        assert_eq!(Instant::now() - start, Duration::ZERO, "a healthy call must not be delayed");
275	    }
276	
277	    #[tokio::test(start_paused = true)]
278	    async fn retries_transient_failures_then_succeeds() {
279	        let attempts = Arc::new(Attempts::default());
280	        let a = attempts.clone();
281	
282	        let out: Result<u64, BoxErr> = retry_rpc("flaky call", move || {
283	            let a = a.clone();
284	            async move {
285	                match a.record() {
286	                    0 | 1 => Err("error sending request: connection refused".into()),
287	                    _ => Ok(42),
288	                }
289	            }
290	        })
291	        .await;
292	
293	        assert_eq!(out.expect("third attempt succeeds"), 42);
294	        assert_eq!(attempts.count(), 3, "must stop as soon as an attempt succeeds");
295	        assert_eq!(attempts.gaps(), RPC_RETRY_DELAYS[..2].to_vec());
296	    }
297	
298	    #[tokio::test(start_paused = true)]
299	    async fn gives_up_after_max_attempts_on_the_documented_backoff() {
300	        let attempts = Arc::new(Attempts::default());
301	        let a = attempts.clone();
302	        let start = Instant::now();
303	
304	        let out: Result<u64, BoxErr> = retry_rpc("dead endpoint", move || {
305	            let a = a.clone();
306	            async move {
307	                a.record();
308	                Err("error sending request: connection refused".into())
309	            }
310	        })
311	        .await;
312	
313	        assert!(out.is_err(), "an endpoint that never answers must surface an error");
314	        assert_eq!(attempts.count(), RPC_MAX_ATTEMPTS);
315	        assert_eq!(attempts.gaps(), RPC_RETRY_DELAYS.to_vec());
316	        assert_eq!(Instant::now() - start, Duration::from_secs(5 + 15 + 45));
