319	    #[tokio::test(start_paused = true)]
320	    async fn propagates_the_final_error_string_verbatim() {
321	        // The dispatcher and the tasks route on `e.to_string() == "<sentinel>"`. If
322	        // `retry_rpc` ever wrapped or annotated the error it returns, those exact-match
323	        // arms would stop firing and tasks would get the wrong reschedule - or be dropped.
324	        for sentinel in [
325	            "EpochNotFinalized",
326	            "PendingReplacement",
327	            "NonceConsumed",
328	            "Insufficient funds",
329	            "VerificationStarted",
330	            "RootNotConfirmed",
331	            "ExecutionFailed",
332	        ] {
333	            let out: Result<(), BoxErr> =
334	                retry_rpc("sentinel call", || async move { Err(sentinel.into()) }).await;
335	            assert_eq!(
336	                out.expect_err("every attempt failed").to_string(),
337	                sentinel,
338	                "retry_rpc must not rewrite the sentinel the dispatcher matches on"
339	            );
340	        }
341	
342	        // The outbox revert is matched by substring, so it has to survive intact too.
343	        let out: Result<(), BoxErr> = retry_rpc("reverting call", || async {
344	            Err("server returned an error response: execution reverted: Invalid claim.".into())
345	        })
346	        .await;
347	        assert!(
348	            out.expect_err("every attempt failed").to_string().contains("Invalid claim"),
349	            "the outbox revert string must reach the dispatcher's `contains` arm"
350	        );
351	    }
