151	/// Strips path/query from an RPC URL so it's safe to log (RPC URLs commonly embed
152	/// API keys in the path, e.g. `https://rpc.ankr.com/eth_sepolia/<key>`).
153	fn redact_url(url: &str) -> String {
154	    match url.split_once("://") {
155	        Some((scheme, rest)) => {
156	            // Secrets can appear in the path (`/eth_sepolia/<key>`), the query string
157	            // (`?apikey=<key>`), or userinfo (`user:pass@host`) - strip all three.
158	            let host_and_after = rest.split_once('@').map_or(rest, |(_, after)| after);
159	            let host = host_and_after
160	                .split(['/', '?', '#'])
161	                .next()
162	                .unwrap_or(host_and_after);
163	            format!("{scheme}://{host}")
164	        }
165	        None => "unknown".to_string(),
166	    }
167	}
