251	    fn parse_rpc_urls(env_var: &str) -> Vec<String> {
252	        std::env::var(env_var)
253	            .expect(&format!("{} must be set", env_var))
254	            .split(',')
255	            .map(|s| s.trim().to_string())
256	            .filter(|s| !s.is_empty())
257	            .collect()
