266	            &std::env::var("WETH_GNOSIS")
267	                .expect("WETH_GNOSIS must be set")
268	        )?;
269	
270	        let private_key = std::env::var("PRIVATE_KEY")
271	            .or_else(|_| std::fs::read_to_string("/run/secrets/validator_key")
272	                .map(|s| s.trim().to_string()))
273	            .expect("PRIVATE_KEY not set or /run/secrets/validator_key not found");
274	
275	        use alloy::signers::local::PrivateKeySigner;
276	        let signer = PrivateKeySigner::from_str(&private_key)?;
277	        let wallet = EthereumWallet::from(signer);
278	
279	        let mut chains = HashMap::new();
280	        chains.insert(42161, ChainInfo {
281	            name: "Arbitrum".to_string(),
282	            rpc_urls: arbitrum_rpcs,
283	            deposit_token: None,
284	            avg_block_millis: 250,
285	        });
286	        chains.insert(1, ChainInfo {
287	            name: "Ethereum".to_string(),
288	            rpc_urls: ethereum_rpcs,
289	            deposit_token: None,
290	            avg_block_millis: 12000,
291	        });
292	        chains.insert(100, ChainInfo {
293	            name: "Gnosis".to_string(),
294	            rpc_urls: gnosis_rpcs,
295	            deposit_token: Some(weth_gnosis),
296	            avg_block_millis: 5000,
297	        });
298	
299	        let inbox_arb_to_eth = Address::from_str(
