301	                .expect("VEA_INBOX_ARB_TO_ETH must be set")
302	        )?;
303	        let outbox_arb_to_eth = Address::from_str(
304	            &std::env::var("VEA_OUTBOX_ARB_TO_ETH")
305	                .expect("VEA_OUTBOX_ARB_TO_ETH must be set")
306	        )?;
307	        let inbox_arb_to_gnosis = Address::from_str(
308	            &std::env::var("VEA_INBOX_ARB_TO_GNOSIS")
309	                .expect("VEA_INBOX_ARB_TO_GNOSIS must be set")
310	        )?;
311	        let outbox_arb_to_gnosis = Address::from_str(
