313	                .expect("VEA_OUTBOX_ARB_TO_GNOSIS must be set")
314	        )?;
315	        let arb_outbox = Address::from_str(
316	            &std::env::var("ARB_OUTBOX")
317	                .expect("ARB_OUTBOX must be set")
318	        )?;
319	
320	        let make_claims = std::env::var("MAKE_CLAIMS")
321	            .map(|v| v.to_lowercase() == "true" || v == "1")
322	            .expect("MAKE_CLAIMS must be set");
323	
324	        let sequencer_inbox = std::env::var("SEQUENCER_INBOX")
