/// Startup-path tests, driven by the in-process fault transport rather than a devnet.
///
/// `get_avg_block_time_ms` is private, so this has to live in-crate: it is also the one
/// startup computation that silently poisons everything downstream if it is wrong, since
/// `relay_delay_secs` is derived from it and an under-estimate schedules a relay before
/// the assertion can possibly have been confirmed.
#[cfg(test)]
mod tests {
    use super::*;
    use crate::contracts::{IOutbox, IRollup, IVeaOutbox};
    use crate::test_support::{Call, Fault, FaultTransport, address_word, block, word};
    use alloy::primitives::address;
    use alloy::sol_types::SolCall;

    /// Resolves the block tag of an `eth_getBlockByNumber` against a fixed chain head.
    fn tag_to_number(call: &Call, latest: u64) -> Option<u64> {
        match call.param(0).as_str()? {
            "latest" | "pending" | "safe" | "finalized" => Some(latest),
            "earliest" => Some(0),
            hex => u64::from_str_radix(hex.trim_start_matches("0x"), 16).ok(),
        }
    }

    /// A chain whose head is `latest` and whose block `n` has timestamp `ts(n)`.
    fn chain<T>(latest: u64, ts: T) -> FaultTransport
    where
        T: Fn(u64) -> u64 + Send + Sync + 'static,
    {
        FaultTransport::new(move |call| match tag_to_number(call, latest) {
            Some(n) if n <= latest => Fault::Ok(block(n, ts(n))),
            // Anything above the head is a block the node genuinely does not have yet.
            _ => Fault::null(),
        })
    }

    #[tokio::test(start_paused = true)]
    async fn avg_block_time_measures_the_full_sample_window() {
        // 250ms blocks, the Arbitrum figure the route timings are sized around.
        let t = chain(10_500, |n| 1_000_000 + n / 4);

        assert_eq!(get_avg_block_time_ms(&t.provider()).await, 250);
        assert_eq!(t.count_of("eth_getBlockByNumber"), 2, "one head sample, one lookback sample");
    }

    #[tokio::test(start_paused = true)]
    async fn avg_block_time_clamps_the_lookback_to_genesis_on_a_short_chain() {
        // A 100-block chain is shorter than BLOCK_TIME_SAMPLE_BLOCKS. An unclamped
        // `latest - 10_000` underflows (panic in debug, a ~1.8e19 block number in
        // release, which the node answers `null` to). 12s blocks over 100 blocks.
        let t = chain(100, |n| 1_000 + 12 * n);

        // 12000, not 120: the divisor has to be the *actual* delta of 100 blocks, not
        // the 10_000 constant, or a fresh devnet reports 100x-too-fast blocks and
        // `relay_delay_secs` collapses to well under the confirmation period.
        assert_eq!(get_avg_block_time_ms(&t.provider()).await, 12_000);
    }

    #[tokio::test(start_paused = true)]
    async fn avg_block_time_survives_a_genesis_only_chain() {
        // latest == 0: the block delta is zero, and only the `.max(1)` keeps this from
        // being a divide-by-zero panic in the very first thing startup does.
        let t = chain(0, |_| 1_700_000_000);

        assert_eq!(get_avg_block_time_ms(&t.provider()).await, 0);
    }

    #[tokio::test(start_paused = true)]
    async fn avg_block_time_retries_a_null_head_instead_of_panicking() {
        // A node mid-sync answers `null` for the head it is about to have. The first
        // call is nulled, the retry must recover rather than hitting the `.expect`.
        let t = FaultTransport::new(|call| match call.method_index {
            0 => Fault::null(),
            _ => match tag_to_number(call, 10_500) {
                Some(n) => Fault::Ok(block(n, 1_000_000 + n / 4)),
                None => Fault::null(),
            },
        });

        assert_eq!(get_avg_block_time_ms(&t.provider()).await, 250);
        assert_eq!(t.count_of("eth_getBlockByNumber"), 3, "one nulled head, then head + lookback");
    }

    /// Outbox parameters, as a fault script over `eth_call`.
    fn outbox_params(
        sequencer_delay_limit: u64,
        min_challenge_period: u64,
        epoch_period: u64,
    ) -> FaultTransport {
        FaultTransport::new(move |call| {
            if call.selector_is(IVeaOutbox::sequencerDelayLimitCall::SELECTOR) {
                Fault::Ok(word(sequencer_delay_limit))
            } else if call.selector_is(IVeaOutbox::minChallengePeriodCall::SELECTOR) {
                Fault::Ok(word(min_challenge_period))
            } else if call.selector_is(IVeaOutbox::epochPeriodCall::SELECTOR) {
                Fault::Ok(word(epoch_period))
            } else {
                Fault::Transport(alloy::transports::TransportErrorKind::custom_str(
                    "unexpected call on the outbox chain",
                ))
            }
        })
    }

    /// Arbitrum side: block sampling plus the rollup lookup and its confirm period.
    fn arb_chain(rollup: alloy::primitives::Address, confirm_period_blocks: u64) -> FaultTransport {
        FaultTransport::new(move |call| {
            if call.method == "eth_getBlockByNumber" {
                return match tag_to_number(call, 10_500) {
                    Some(n) => Fault::Ok(block(n, 1_000_000 + n / 4)),
                    None => Fault::null(),
                };
            }
            if call.selector_is(IOutbox::rollupCall::SELECTOR) {
                Fault::Ok(address_word(rollup))
            } else if call.selector_is(IRollup::confirmPeriodBlocksCall::SELECTOR) {
                Fault::Ok(word(confirm_period_blocks))
            } else {
                Fault::Transport(alloy::transports::TransportErrorKind::custom_str(
                    "unexpected call on the Arbitrum chain",
                ))
            }
        })
    }

    fn route(outbox: &FaultTransport, arb: &FaultTransport) -> Route {
        Route {
            name: "ARB_TO_ETH",
            inbox_chain_id: 42161,
            inbox_address: address!("0000000000000000000000000000000000000011"),
            inbox_provider: arb.provider(),
            inbox_avg_block_millis: 250,
            outbox_chain_id: 1,
            outbox_address: address!("0000000000000000000000000000000000000022"),
            outbox_provider: outbox.provider(),
