//! RPC failure-mode integration tests.
//!
//! These run against the in-process fault transport in `tests/fake_rpc`, **not** against
//! the anvil devnet: they need endpoints that lie, lag, rate-limit and hang, none of
//! which anvil will do on request. Nothing here is `#[serial]`, nothing here binds a
//! port, and every one is safe to run in CI with no chain present.
//!
//! All timing-sensitive cases run on a paused tokio clock, because a full `retry_rpc`
//! exhaustion sleeps 5+15+45 = 65 seconds of wall time per call site.

mod fake_rpc;

use alloy::primitives::{Address, address};
use alloy::sol_types::SolCall;
use fake_rpc::{Fault, FaultTransport, address_word, block, tag_to_number, word};
use serde_json::json;
use std::time::Duration;
use vea_validator::config::{Route, RouteSettings};
use vea_validator::startup::{check_rpc_health, load_route_settings};

/// Attempts `retry_rpc` makes before giving up: the initial call plus one per entry in
/// `RPC_RETRY_DELAYS`. Mirrored here because the constant is crate-private.
const RPC_MAX_ATTEMPTS: usize = 4;

const ARB_OUTBOX: Address = address!("0000000000000000000000000000000000000044");
const ROLLUP: Address = address!("0000000000000000000000000000000000000033");

/// The two routes `check_rpc_health` expects, wired to three independent fake endpoints.
///
/// `check_rpc_health` indexes `routes[0]` and `routes[1]` directly, so the shape of this
/// vector is load-bearing.
fn routes(arb: &FaultTransport, eth: &FaultTransport, gnosis: &FaultTransport) -> Vec<Route> {
    let mk = |name, outbox_chain_id, outbox: &FaultTransport| Route {
        name,
        inbox_chain_id: 42161,
        inbox_address: address!("0000000000000000000000000000000000000011"),
        inbox_provider: arb.provider(),
        inbox_avg_block_millis: 250,
        outbox_chain_id,
        outbox_address: address!("0000000000000000000000000000000000000022"),
        outbox_provider: outbox.provider(),
        weth_address: None,
        settings: RouteSettings::test_defaults(),
    };
    vec![mk("ARB_TO_ETH", 1, eth), mk("ARB_TO_GNOSIS", 100, gnosis)]
}

/// An endpoint that answers every `eth_blockNumber` with the same height.
fn healthy_head(number: u64) -> FaultTransport {
    FaultTransport::new(move |_| {
        Fault::Ok(json!(alloy::primitives::U256::from(number).to_string()))
    })
}

// ---------------------------------------------------------------------------
// check_rpc_health
// ---------------------------------------------------------------------------

#[tokio::test(start_paused = true)]
async fn a_json_rpc_error_over_http_200_fails_the_health_check() {
    // The dangerous shape: HTTP 200, so nothing at the transport layer notices, with a
    // JSON-RPC error object in the body. An endpoint like this answers fast and would
    // otherwise keep winning the fallback race forever (see `ErrorAwareTransport`).
    let arb = FaultTransport::new(|_| Fault::RpcError {
        code: -32601,
        message: "the method eth_blockNumber does not exist/is not available".to_string(),
    });
    let eth = healthy_head(21_000_000);
    let gnosis = healthy_head(38_000_000);
    let routes = routes(&arb, &eth, &gnosis);

    let err = check_rpc_health(&routes)
        .await
        .expect_err("an endpoint that cannot answer eth_blockNumber is not healthy");

    // Startup wraps the error with a FATAL prefix. That is safe *here* - this path never
    // reaches the dispatcher's exact-match sentinel arms - but the underlying provider
    // error still has to survive into the message, or an operator gets no diagnosis.
    let msg = err.to_string();
    assert!(
        msg.starts_with("FATAL: Arbitrum RPC unreachable or unhealthy:"),
        "unexpected message: {msg}"
    );
    assert!(msg.contains("does not exist"), "provider error was swallowed: {msg}");

    assert_eq!(arb.call_count(), RPC_MAX_ATTEMPTS, "the failing call must be retried");
    assert_eq!(eth.call_count(), 0, "startup must stop at the first unhealthy chain");
}

#[tokio::test(start_paused = true)]
async fn rate_limiting_fails_the_health_check_only_after_the_full_backoff() {
    // A 429 is transient by nature, so giving up on the first one would refuse to start
    // a validator that a few seconds of backoff would have brought up.
    let arb = healthy_head(300_000_000);
    let eth = FaultTransport::new(|_| Fault::rate_limited());
    let gnosis = healthy_head(38_000_000);
    let routes = routes(&arb, &eth, &gnosis);

    let err = check_rpc_health(&routes).await.expect_err("a 429 on every attempt is fatal");

    assert!(
        err.to_string().starts_with("FATAL: Ethereum RPC unreachable or unhealthy:"),
        "unexpected message: {err}"
    );
    assert_eq!(eth.call_count(), RPC_MAX_ATTEMPTS);
    assert_eq!(gnosis.call_count(), 0);
}

#[tokio::test(start_paused = true)]
async fn the_health_check_rides_out_a_transient_outage_on_every_chain() {
    // Each endpoint refuses the first two connections. Startup must come up anyway:
    // refusing to start costs liveness, and liveness is the whole security argument.
    let flaky = |height: u64| {
        FaultTransport::new(move |call| match call.method_index {
            0 | 1 => Fault::unreachable(),
            _ => Fault::Ok(json!(alloy::primitives::U256::from(height).to_string())),
        })
    };
    let (arb, eth, gnosis) = (flaky(300_000_000), flaky(21_000_000), flaky(38_000_000));
    let routes = routes(&arb, &eth, &gnosis);

    check_rpc_health(&routes).await.expect("two transient failures must not stop startup");

    assert_eq!(arb.call_count(), 3);
    assert_eq!(eth.call_count(), 3);
    assert_eq!(gnosis.call_count(), 3);
}

#[tokio::test(start_paused = true)]
async fn a_hung_endpoint_never_returns_on_its_own() {
    // An endpoint that accepts the connection and then goes silent is the one failure
    // mode `retry_rpc` cannot handle by itself: there is no timeout in the retry loop,
    // only the 30s reqwest timeout in `config::build_http_client`. This pins that fact -
    // if the request timeout were ever dropped from the real transport, startup would
    // hang here forever instead of failing over, and the bot would be silently absent.
    let arb = FaultTransport::new(|_| Fault::Hang);
    let eth = healthy_head(21_000_000);
    let gnosis = healthy_head(38_000_000);
    let routes = routes(&arb, &eth, &gnosis);

    let outcome = tokio::time::timeout(Duration::from_secs(600), check_rpc_health(&routes)).await;

    assert!(outcome.is_err(), "a hung transport with no timeout must not resolve");
    assert_eq!(arb.call_count(), 1, "the first request never came back, so none followed");
}

// ---------------------------------------------------------------------------
// retry_rpc_opt through the public block-search API
// ---------------------------------------------------------------------------

#[tokio::test(start_paused = true)]
async fn a_null_head_is_retried_rather_than_treated_as_a_missing_block() {
    // A node mid-sync answers `null` fastest, precisely because it has no block to
    // fetch. Accepting that would hand `None` to a caller that panics on it.
    let t = FaultTransport::new(|call| match call.method_index {
        0 => Fault::null(),
        _ => Fault::Ok(block(1_000, 1_010_000)),
    });

    let found = vea_validator::find_block_by_timestamp(&t.provider(), 2_000_000).await;

    assert_eq!(found, 1_000);
    assert_eq!(t.call_count(), 2, "one null, one retry");
}

#[tokio::test(start_paused = true)]
#[should_panic(expected = "Block latest not found")]
async fn a_permanently_null_head_fails_loudly_instead_of_returning_block_zero() {
    // Silently returning 0 would make the indexer rescan from genesis, or worse, make a
    // timestamp search answer with a block that has nothing to do with the epoch.
    let t = FaultTransport::new(|_| Fault::null());
    let _ = vea_validator::find_block_by_timestamp(&t.provider(), 2_000_000).await;
}

#[tokio::test(start_paused = true)]
async fn the_timestamp_binary_search_survives_rate_limits_mid_search() {
    // ~10 block fetches, with every other request 429'd. The answer must be identical to
    // the clean-endpoint answer: the first block at or after the target timestamp.
    let t = FaultTransport::new(|call| {
        if call.index % 2 == 1 {
            return Fault::rate_limited();
        }
        match tag_to_number(call, 1_000) {
            Some(n) => Fault::Ok(block(n, 1_000_000 + 10 * n)),
            None => Fault::null(),
        }
    });

    let found = vea_validator::find_block_by_timestamp(&t.provider(), 1_005_000).await;

    assert_eq!(found, 500, "block 500 is the first with timestamp >= 1_005_000");
}

// ---------------------------------------------------------------------------
// load_route_settings
// ---------------------------------------------------------------------------

#[tokio::test(start_paused = true)]
async fn route_settings_load_through_a_half_broken_endpoint() {
    // Every other request fails: two with a 429, two with a JSON-RPC error over HTTP 200,
    // rotating. Getting these values wrong is not a startup inconvenience - they set the
    // relay delay and the sync lookback, so an endpoint that degrades during startup must
    // either produce the right numbers or not produce any.
    let fault_for = |index: usize| match index % 4 {
        1 => Fault::rate_limited(),
        3 => Fault::RpcError {
            code: -32005,
            message: "rate limit exceeded".to_string(),
        },
        _ => Fault::Ok(serde_json::Value::Null), // replaced by the caller
    };

    let arb = FaultTransport::new(move |call| {
        if call.index % 2 == 1 {
            return fault_for(call.index);
        }
        if call.method == "eth_getBlockByNumber" {
            return match tag_to_number(call, 10_500) {
                Some(n) => Fault::Ok(block(n, 1_000_000 + n / 4)),
                None => Fault::null(),
            };
        }
        if call.selector_is(vea_validator::contracts::IOutbox::rollupCall::SELECTOR) {
            Fault::Ok(address_word(ROLLUP))
        } else if call
            .selector_is(vea_validator::contracts::IRollup::confirmPeriodBlocksCall::SELECTOR)
        {
            Fault::Ok(word(45_818))
        } else {
            Fault::unreachable()
        }
    });

    let outbox = FaultTransport::new(move |call| {
        use vea_validator::contracts::IVeaOutbox;
        if call.index % 2 == 1 {
            return fault_for(call.index);
        }
        if call.selector_is(IVeaOutbox::sequencerDelayLimitCall::SELECTOR) {
            Fault::Ok(word(86_400))
        } else if call.selector_is(IVeaOutbox::minChallengePeriodCall::SELECTOR) {
            Fault::Ok(word(10_800))
        } else if call.selector_is(IVeaOutbox::epochPeriodCall::SELECTOR) {
            Fault::Ok(word(7_200))
        } else {
            Fault::unreachable()
        }
    });

    let routes = routes(&arb, &outbox, &outbox);
    let settings = load_route_settings(&routes[0], ARB_OUTBOX, &arb.provider()).await;

    // 45_818 confirmation blocks x 250ms = 11_454s, plus the 10min safety buffer.
    assert_eq!(settings.relay_delay_secs, 11_454 + 600);
    assert_eq!(settings.start_verification_delay, 86_400 + 7_200 + 600);
    assert_eq!(settings.min_challenge_period, 10_800 + 600);
    assert_eq!(
        settings.sync_lookback_secs,
        (11_454 + 600) + (86_400 + 7_200 + 600) + (10_800 + 600) + 600
    );

    // Two block samples and two rollup reads, each retried once.
    assert_eq!(arb.call_count(), 8);
    // Three outbox parameters, each retried once.
    assert_eq!(outbox.call_count(), 6);
}

