#[tokio::test(start_paused = true)]
async fn route_settings_load_through_a_half_broken_endpoint() {
    // Every other request fails: two with a 429, two with a JSON-RPC error over HTTP 200,
    // rotating. Getting these values wrong is not a startup inconvenience - they set the
    // relay delay and the sync lookback, so an endpoint that degrades during startup must
    // either produce the right numbers or not produce any.
    let fault_for = |index: usize| match index % 4 {
        1 => Fault::rate_limited(),
        3 => Fault::RpcError {
            code: -32005,
            message: "rate limit exceeded".to_string(),
        },
        _ => Fault::Ok(serde_json::Value::Null), // replaced by the caller
    };

    let arb = FaultTransport::new(move |call| {
        if call.index % 2 == 1 {
            return fault_for(call.index);
        }
        if call.method == "eth_getBlockByNumber" {
            return match tag_to_number(call, 10_500) {
                Some(n) => Fault::Ok(block(n, 1_000_000 + n / 4)),
                None => Fault::null(),
            };
        }
        if call.selector_is(vea_validator::contracts::IOutbox::rollupCall::SELECTOR) {
            Fault::Ok(address_word(ROLLUP))
        } else if call
            .selector_is(vea_validator::contracts::IRollup::confirmPeriodBlocksCall::SELECTOR)
        {
            Fault::Ok(word(45_818))
        } else {
            Fault::unreachable()
        }
    });

    let outbox = FaultTransport::new(move |call| {
        use vea_validator::contracts::IVeaOutbox;
        if call.index % 2 == 1 {
            return fault_for(call.index);
        }
        if call.selector_is(IVeaOutbox::sequencerDelayLimitCall::SELECTOR) {
            Fault::Ok(word(86_400))
        } else if call.selector_is(IVeaOutbox::minChallengePeriodCall::SELECTOR) {
            Fault::Ok(word(10_800))
        } else if call.selector_is(IVeaOutbox::epochPeriodCall::SELECTOR) {
            Fault::Ok(word(7_200))
        } else {
            Fault::unreachable()
        }
    });

    let routes = routes(&arb, &outbox, &outbox);
    let settings = load_route_settings(&routes[0], ARB_OUTBOX, &arb.provider()).await;

    // 45_818 confirmation blocks x 250ms = 11_454s, plus the 10min safety buffer.
    assert_eq!(settings.relay_delay_secs, 11_454 + 600);
    assert_eq!(settings.start_verification_delay, 86_400 + 7_200 + 600);
    assert_eq!(settings.min_challenge_period, 10_800 + 600);
    assert_eq!(
        settings.sync_lookback_secs,
        (11_454 + 600) + (86_400 + 7_200 + 600) + (10_800 + 600) + 600
    );

    // Two block samples and two rollup reads, each retried once.
    assert_eq!(arb.call_count(), 8);
    // Three outbox parameters, each retried once.
    assert_eq!(outbox.call_count(), 6);
}

