/// Tests for the failover classification layer and URL redaction.
///
/// `ErrorAwareTransport` sits on the boundary between "this endpoint is broken" and
/// "the contract said no". Getting that boundary wrong in either direction is a real
/// hazard: too eager, and a contract revert gets rewritten into a transport error,
/// destroying the `"Invalid claim."` substring the dispatcher reschedules on; too lax,
/// and a fast-failing misconfigured endpoint wins the fallback race forever.
#[cfg(test)]
mod tests {
    use super::*;
    use crate::test_support::{Fault, FaultTransport};
    use alloy::providers::Provider;

    #[test]
    fn infra_errors_are_classified_as_endpoint_failures() {
        assert!(is_infra_rpc_error(-32603, "internal error"));
        assert!(is_infra_rpc_error(-32005, "limit exceeded"));
        assert!(is_infra_rpc_error(-32000, "Unauthorized"));
        assert!(is_infra_rpc_error(-32000, "invalid API key"));
        assert!(is_infra_rpc_error(-32000, "rate limit exceeded"));
        assert!(is_infra_rpc_error(429, "Too Many Requests"));
    }

    #[test]
    fn a_contract_revert_is_never_reclassified() {
        // The outbox reverts with "Invalid claim." whenever the preimage a task holds no
        // longer matches `claimHashes[epoch]` - the normal, expected outcome of losing a
        // race. Rewriting it into a transport error would blank the dispatcher's
        // `contains("Invalid claim")` arm, and the task would be dropped or retried on
        // the wrong schedule instead of being re-derived against the current claim.
        assert!(!is_infra_rpc_error(3, "execution reverted: Invalid claim."));
        assert!(!is_infra_rpc_error(
            -32000,
            "execution reverted: Invalid claim."
        ));
        // -32000 is a provider-defined catch-all; several nodes use it for plain reverts,
        // which is why the code alone must not decide.
        assert!(!is_infra_rpc_error(-32000, "execution reverted"));
        assert!(!is_infra_rpc_error(-32015, "VM execution error"));
    }

    fn wrapped(fault: impl Fn() -> Fault + Send + Sync + 'static) -> DynProvider<Ethereum> {
        let transport = ErrorAwareTransport {
            inner: FaultTransport::new(move |_| fault()),
            label: "https://fake.invalid".to_string(),
        };
        let client = RpcClient::builder().transport(transport, false);
        DynProvider::new(ProviderBuilder::new().connect_client(client))
    }

    #[tokio::test]
    async fn an_infra_error_over_http_200_surfaces_as_a_transport_error() {
        // HTTP 200 with a JSON-RPC error body: the shape `FallbackLayer` does not score
        // down on its own. Only by turning it into a transport error does the fan-out
        // actually route around the endpoint.
        let provider = wrapped(|| Fault::RpcError {
            code: -32603,
            message: "internal error".to_string(),
        });

        let err = provider
            .get_block_number()
            .await
            .expect_err("an infra-level error is not a usable answer");
        let msg = err.to_string();
        assert!(msg.contains("error code -32603"), "unexpected message: {msg}");
        assert!(
            matches!(err, alloy::transports::RpcError::Transport(_)),
            "must be a transport error, or the fallback layer will not fail over: {msg}"
        );
    }

    #[tokio::test]
    async fn a_revert_passes_through_with_its_message_intact() {
        let provider = wrapped(|| Fault::RpcError {
            code: 3,
            message: "execution reverted: Invalid claim.".to_string(),
        });

        let err = provider
            .get_block_number()
            .await
            .expect_err("the node refused the call");
        assert!(
            err.to_string().contains("Invalid claim."),
            "the revert string the dispatcher matches on must survive: {err}"
        );
        assert!(
            matches!(err, alloy::transports::RpcError::ErrorResp(_)),
            "a revert is an application answer, not a broken endpoint"
        );
    }

    #[test]
    fn redaction_strips_every_place_an_api_key_hides() {
        assert_eq!(
            redact_url("https://rpc.example.com/eth_sepolia/deadbeefkey"),
            "https://rpc.example.com"
        );
        assert_eq!(
            redact_url("https://rpc.example.com?apikey=deadbeefkey"),
            "https://rpc.example.com"
        );
        assert_eq!(
            redact_url("https://user:secret@rpc.example.com/v1"),
            "https://rpc.example.com"
        );
        assert_eq!(redact_url("not a url"), "unknown");
    }
}

